  Object.assign(messages.es, {"home": "Inicio", "sources": "Fuentes", "analysis": "Análisis", "welcomeEyebrow": "DE LOS REGISTROS A LA INFORMACIÓN", "welcomeHeading": "Explora, comprende y conserva tu análisis.", "welcomeText": "Un espacio para consultar catálogos sísmicos, examinar su procedencia y obtener información descriptiva reutilizable.", "openExplorer": "Explorar el mapa", "browseSources": "Conocer las fuentes", "availableCatalogs": "catálogos conservados", "sourceRecords": "registros de origen", "frozenInteractive": "Mapas históricos interactivos. Las observaciones son instantáneas fijadas, no un flujo en tiempo real.", "workflowSources": "Elige la evidencia", "workflowSourcesText": "Cuatro catálogos de tres distribuidores, con cobertura, campos y hashes explícitos.", "viewSources": "Ver fuentes", "workflowExplore": "Define tu consulta", "workflowExploreText": "Selecciona región terrestre, periodo y magnitud reportada; revisa el mapa y la tabla.", "viewMap": "Ver mapa", "workflowAnalyze": "Obtén información", "workflowAnalyzeText": "Consulta estadísticos por catálogo y tipo de magnitud, conteos anuales y asociaciones descriptivas.", "viewAnalysis": "Ver análisis", "workflowExport": "Reutiliza el resultado", "workflowExportText": "Descarga registros CSV, consulta JSON, resumen CSV o un informe HTML imprimible con evidencia.", "viewDeliverables": "Ver entregables", "technologyHeading": "Una arquitectura reproducible", "technologyText": "Preparación y validación con Python; paquetes JSON y manifiestos SHA-256; interfaz HTML, CSS y JavaScript con Leaflet; publicación estática en GitHub Pages. La consulta no necesita un servidor de base de datos, Docker, PHP ni Java.", "sourceInventory": "INVENTARIO DE DATOS CONSERVADOS", "sourceHeading": "Cuatro catálogos, tres distribuidores", "sourceInventoryText": "Consulta cada entrada antes de seleccionarla. Distribuidor, país cartográfico y mapa base son elecciones distintas.", "sourceCoverage": "Cobertura / selección", "sourceRows": "Registros", "sourceSemantics": "Claves y unidades", "sourceEvidence": "Datos y evidencia", "inventoryScope": "Son paquetes de archivos preservados, no cuatro bases de datos independientes ni una validación cruzada de los mismos terremotos.", "normalizationEyebrow": "REGLAS DE INTEGRACIÓN", "normalizationHeading": "Un formato común, con diferencias explícitas", "normShape": "Estructura y tiempos", "normShapeText": "Adaptadores por fuente convierten los campos disponibles al esquema de consulta. La fecha y hora UTC se escriben en ISO 8601; los textos y relojes crudos se conservan cuando existen. Los vacíos de origen se conservan; los campos comunes no suministrados quedan null.", "normUnits": "Valores y unidades", "normUnitsText": "Coordenadas y magnitudes reportadas no se corrigen. El tipo de magnitud se conserva literalmente, sin convertir a Mw. Sólo las profundidades con unidad km documentada entran al campo común; la profundidad canadiense queda como valor crudo de unidad desconocida.", "normIdentity": "Identidad y relaciones", "normIdentityText": "Los IDs USGS se conservan; SSN y NRCan usan claves de fila derivadas, no nuevos IDs oficiales. La vista conjunta añade catálogo y procedencia. Sólo la igualdad exacta de IDs ComCat entre sus dos paquetes genera una marca de coincidencia; todas las filas se retienen.", "normLimits": "Interpretación", "normLimitsText": "No se vinculan eventos entre agencias por cercanía espacio-temporal, ni se fusionan automáticamente. La etiqueta de país deriva de polígonos terrestres Natural Earth. Correlación estadística no significa identidad de evento, independencia, causalidad o pronóstico.", "analysisEyebrow": "INFORMACIÓN DERIVADA DE TU CONSULTA", "analysisHeading": "Resultados descriptivos en pantalla", "editQuery": "Editar consulta en el mapa", "analysisScope": "Los resultados se actualizan con los mismos registros filtrados. Las medidas de magnitud se separan por catálogo y tipo exacto; el tipo no reportado forma su propio grupo. No se homogeneizan escalas ni se estiman probabilidades sísmicas.", "selectedRecords": "Registros seleccionados", "activeCatalogs": "Catálogos activos", "reportedGroups": "Grupos catálogo / tipo M", "selectedPeriod": "Periodo UTC seleccionado", "magnitudeStatistics": "Magnitudes reportadas por grupo", "magnitudeStatisticsNote": "Media y dispersión aritméticas de los valores retenidos; un grupo de tipo desconocido no acredita una escala homogénea.", "statMean": "Media", "statMedian": "Mediana", "statMin": "Mínimo", "statMax": "Máximo", "statSD": "Desv. estándar muestral", "statDepthMean": "Profundidad media km (n)", "correlationHeading": "Asociación magnitud–profundidad", "correlationNote": "Pearson se calcula sólo dentro de un catálogo y un tipo de magnitud reportado, con profundidad documentada en km y al menos tres pares variables. No vincula registros entre fuentes.", "pairedRecords": "Pares válidos", "pearsonCoefficient": "r de Pearson", "interpretation": "Interpretación", "correlationDescriptive": "Asociación descriptiva; no implica causalidad ni predicción.", "correlationUnavailable": "No calculable: tipo desconocido, unidad no documentada, pocos pares o varianza nula.", "annualAnalysis": "Conteos anuales de la selección", "annualAnalysisNote": "Un año sin filas seleccionadas no establece ausencia física de sismos. El último año de la fuente puede ser parcial.", "annualTable": "Consultar tabla anual", "utcYear": "Año UTC", "deliverablesEyebrow": "DEL ANÁLISIS A LA REUTILIZACIÓN", "deliverablesHeading": "Entregables con su evidencia", "deliverablesText": "Todos describen la misma selección, sin limitarla al encuadre visible del mapa.", "summaryCsv": "Resumen estadístico CSV", "analysisJson": "Análisis y evidencia JSON", "htmlReport": "Informe HTML imprimible", "reportScope": "El informe HTML conserva tablas, filtros, hashes y límites; puede abrirse en un navegador e imprimirse. No es un informe de amenaza ni un pronóstico validado.", "analysisUnavailable": "Los resultados estarán disponibles cuando termine la carga de datos.", "analysisSaved": "Entregable generado con los filtros e inputs de esta selección.", "officialId": "ID de evento conservado", "derivedId": "Clave de fila derivada", "unknownDepthUnit": "Profundidad cruda; unidad desconocida", "documentedDepth": "Profundidad documentada en km", "openThisCatalog": "Seleccionar y abrir mapa", "packagedData": "Paquete JSON", "fieldManifest": "Manifiesto / campos y derechos", "sourceHash": "SHA-256 del paquete", "analysisLimit": "Estadísticos de registros seleccionados. La cobertura no acredita completitud ni independencia.", "selectedSource": "Fuente seleccionada", "filtersAndEvidence": "Filtros y evidencia"});
